#!/bin/bash
# serval02 card 1 (while serval05 is busy): bench of the exact-step ideas, then their speed profile at 256 and 512 copies.
U=GPU-fed69954-5a71-dbb2-ee91-544e0eb6b8a3
P=/p/rlprojects/RND/10_jax_exploration_platform
export PYTHONPATH=$P/src PYTHONNOUSERSITE=1 XLA_PYTHON_CLIENT_PREALLOCATE=false
free_check="read MIG USED <<<\"\$(nvidia-smi -i $U --query-gpu=mig.mode.current,memory.used --format=csv,noheader,nounits | tr -d ' ' | tr ',' ' ')\"; PROCS=\$(nvidia-smi --query-compute-apps=gpu_uuid --format=csv,noheader | grep -c $U); if [ \"\$MIG\" != Disabled ] || [ \"\$USED\" -ge 1024 ] || [ \"\$PROCS\" -ne 0 ]; then echo 'serval02 card 1 busy; unit not run'; exit 75; fi; date; echo 'machine: serval02 card 1'"
flock /tmp/sl5nw_serval02_card1.lock bash -c "$free_check
  CUDA_VISIBLE_DEVICES=$U timeout 1750 /p/rlprojects/RND/.venvs/platform_jax/bin/python -u $P/scripts/grid_initialization_campaign/rnd_decay_bench.py --ideas /p/rlprojects/RND/10_jax_exploration_platform/runs/2026-11-09-19-42_online-tabular-rnd-auto-research_reward-normalization-on_even-start-and-decay-exponent-near-minus-0.5_straight-32-snake-16x2_tabular-ppo-coordinate-ppo_five-days/batches/02_stable-shrink-target-exponents-and-count-rate/bench_ideas.json --output /p/rlprojects/RND/10_jax_exploration_platform/runs/2026-11-09-19-42_online-tabular-rnd-auto-research_reward-normalization-on_even-start-and-decay-exponent-near-minus-0.5_straight-32-snake-16x2_tabular-ppo-coordinate-ppo_five-days/bench/batch_02_four_laws --only \$(cat /p/rlprojects/RND/10_jax_exploration_platform/runs/2026-11-09-19-42_online-tabular-rnd-auto-research_reward-normalization-on_even-start-and-decay-exponent-near-minus-0.5_straight-32-snake-16x2_tabular-ppo-coordinate-ppo_five-days/batches/02_stable-shrink-target-exponents-and-count-rate/bench_names_part_2.txt)" > /p/rlprojects/RND/10_jax_exploration_platform/runs/2026-11-09-19-42_online-tabular-rnd-auto-research_reward-normalization-on_even-start-and-decay-exponent-near-minus-0.5_straight-32-snake-16x2_tabular-ppo-coordinate-ppo_five-days/logs/bench_serval02_batch2_part_2.log 2>&1
echo "batch 2 part 2 (exact step) exit $?" >> /p/rlprojects/RND/10_jax_exploration_platform/runs/2026-11-09-19-42_online-tabular-rnd-auto-research_reward-normalization-on_even-start-and-decay-exponent-near-minus-0.5_straight-32-snake-16x2_tabular-ppo-coordinate-ppo_five-days/logs/bench_serval02_runner.log
flock /tmp/sl5nw_serval02_card1.lock bash -c "$free_check
  CUDA_VISIBLE_DEVICES=$U timeout 1500 /p/rlprojects/RND/.venvs/platform_jax/bin/python -u $P/scripts/grid_initialization_campaign/profile_online_tabular.py --ideas /p/rlprojects/RND/10_jax_exploration_platform/runs/2026-11-09-19-42_online-tabular-rnd-auto-research_reward-normalization-on_even-start-and-decay-exponent-near-minus-0.5_straight-32-snake-16x2_tabular-ppo-coordinate-ppo_five-days/batches/02_stable-shrink-target-exponents-and-count-rate/profile_ideas.json --output /p/rlprojects/RND/10_jax_exploration_platform/runs/2026-11-09-19-42_online-tabular-rnd-auto-research_reward-normalization-on_even-start-and-decay-exponent-near-minus-0.5_straight-32-snake-16x2_tabular-ppo-coordinate-ppo_five-days/infrastructure/profiles/serval02_card1_h100_nvl_snake_coordinate-ppo_exact_step.json --copies 256 512 --timed 20
  nvidia-smi --query-compute-apps=pid,used_memory --format=csv,noheader" > /p/rlprojects/RND/10_jax_exploration_platform/runs/2026-11-09-19-42_online-tabular-rnd-auto-research_reward-normalization-on_even-start-and-decay-exponent-near-minus-0.5_straight-32-snake-16x2_tabular-ppo-coordinate-ppo_five-days/logs/profile_serval02_exact_step.log 2>&1
echo "exact-step profile exit $?" >> /p/rlprojects/RND/10_jax_exploration_platform/runs/2026-11-09-19-42_online-tabular-rnd-auto-research_reward-normalization-on_even-start-and-decay-exponent-near-minus-0.5_straight-32-snake-16x2_tabular-ppo-coordinate-ppo_five-days/logs/bench_serval02_runner.log
